const ns='http://www.w3.org/2000/svg';
function shape(tag,attrs,parent){const el=document.createElementNS(ns,tag);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,v));parent.append(el);return el;}
const boards=document.querySelector('#boards'),posts=document.querySelector('#posts');
for(let i=0;i<48;i++){const x=72+i*20;const g=shape('g',{class:'board'},boards);shape('path',{d:`M${x+18} 353l4-3v155l-4 4Z`,fill:'#754930'},g);shape('path',{d:`M${x} 509V353l9-8 9 8v156Z`,fill:'url(#wood)',stroke:'#966041','stroke-width':'.7'},g);shape('path',{d:`M${x} 509V353l9-8 9 8v156Z`,fill:'url(#grain)'},g);shape('circle',{cx:x+9,cy:392,r:1.2,fill:'#785238'},g);shape('circle',{cx:x+9,cy:480,r:1.2,fill:'#785238'},g);}
for(let i=0;i<6;i++){const x=65+i*194;const g=shape('g',{class:'post'},posts);shape('rect',{x,y:334,width:24,height:182,rx:1,fill:'#a86b44'},g);shape('path',{d:`M${x-3} 334l15-10 15 10v6h-30Z`,fill:'#dba176'},g);shape('rect',{x:x+17,y:341,width:7,height:175,fill:'#865537'},g);}
const clamp=x=>Math.max(0,Math.min(1,x));const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let playing=false;
function render(p){p=reduced?1:p;document.querySelector('#house-photo').style.transform=reduced?'none':`translateY(${p*7}px) scale(${1+p*.035})`; document.querySelectorAll('.post').forEach((e,i)=>{const n=clamp((p-i*.025)/.24);e.style.opacity=n;e.style.transform=`translateY(${(1-n)*80}px)`});document.querySelector('#rails').style.opacity=clamp((p-.2)/.2);document.querySelectorAll('.board').forEach((e,i)=>{const n=clamp((p-.32-i*.008)/.23);e.style.opacity=n;e.style.transform=`translateY(${(1-n)*-95}px)`});document.querySelector('#progress').style.width=`${p*100}%`;const stage=p<.3?0:p<.72?1:2;document.querySelector('#stage').textContent=['01 / SET THE POSTS','02 / BUILD THE BOUNDARY','03 / MAKE IT YOURS'][stage];document.querySelector('.scene-no').textContent=`0${stage+1} — 03`;}
function update(){if(!playing){const s=document.querySelector('.scroll-hero');render(clamp(-s.getBoundingClientRect().top/(s.offsetHeight-innerHeight)));}}
let ticking=false;addEventListener('scroll',()=>{if(!ticking){requestAnimationFrame(()=>{update();ticking=false});ticking=true}},{passive:true});addEventListener('resize',update);update();
document.querySelector('#play').onclick=()=>{if(playing)return;playing=true;let start;const animate=t=>{start??=t;const p=clamp((t-start)/5000);render(p);if(p<1)requestAnimationFrame(animate);else playing=false;};requestAnimationFrame(animate)};
const c=window.CLIENT;document.querySelector('.scene').setAttribute('aria-label',c.heroPhoto.alt);document.querySelector('#house-photo').setAttribute('href',c.heroPhoto.src);document.querySelector('#hero-photo-credit').textContent=c.heroPhoto.credit;document.querySelector('#hero-photo-credit').href=c.heroPhoto.source;
const $=s=>document.querySelector(s);
function put(id,value){$('#'+id).textContent=value;}
document.title=c.copy.title; $('meta[name="description"]').content=c.copy.description;
Object.entries({ink:c.theme.ink,cream:c.theme.cream,orange:c.theme.accent,'body-font':c.theme.bodyFont,'heading-font':c.theme.headingFont}).forEach(([k,v])=>document.documentElement.style.setProperty('--'+k,v));
$('#logo').src=c.logo; $('#logo').alt=c.logoAlt; put('brand-name',c.name);
put('location',`${c.copy.eyebrow} · ${c.city.toUpperCase()}, ${c.state.toUpperCase()}`);
const h=$('#headline');h.append(document.createTextNode(c.copy.headline[0]),document.createElement('br'),document.createTextNode(c.copy.headline[1]));const em=document.createElement('em');em.textContent=c.copy.headline[2];h.append(em);
put('intro',c.copy.intro);put('hero-cta',c.copy.cta);put('local-note',c.copy.localNote);
const review=document.createElement('a'); review.href=c.reviewsUrl;review.target='_blank';review.rel='noopener';review.setAttribute('aria-label', `${c.rating} out of 5 stars, ${c.reviews} Google reviews`);const stars=document.createElement('span');stars.className='rating-stars';stars.setAttribute('aria-hidden','true');stars.textContent='★★★★★';review.append(stars,document.createTextNode(` ${c.rating} · ${c.reviews} Google reviews`));$('#trust').append(review);if(c.ownerOperated){const span=document.createElement('span');span.textContent='✓ Owner-operated';$('#trust').append(span);}
for(const id of ['materials','work','services','quote']){put(id+'-title',c.copy[id+'Title']);put(id+'-intro',c.copy[id+'Intro']);}
put('price-note',c.copy.priceNote);put('area-list','Serving '+c.serviceAreas.join(', ')+', and nearby communities.');
put('footer-name',c.name);put('footer-location',`${c.city}, ${c.state} · ${c.county}`);
document.querySelectorAll('[data-call]').forEach(a=>{a.href='tel:'+c.phoneE164;a.textContent='Call '+c.phone;});$('#footer-email').href='mailto:'+c.email;$('#footer-email').textContent=c.email;$('#official-contact').href=c.contactUrl;
const money=n=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',maximumFractionDigits:0}).format(n);
for(const m of c.materials){const card=document.createElement('article');card.className='material-card';const image=m.photo?document.createElement('img'):document.createElement('div');if(m.photo){image.src=m.photo;image.alt=m.name+' fence';image.loading='lazy';}else{image.className='material-swatch '+m.id;image.setAttribute('aria-hidden','true');}card.append(image);const content=document.createElement('div');for(const [tag,text,cls] of [['small',m.tag,''],['h3',m.name,''],['p',m.description,''],['strong',`${money(m.low)}–${money(m.high)} / foot`,'material-price'],['p','Provisional installed planning range','muted'],['p','Upkeep: '+m.upkeep,'spec'],['p','Lifespan: '+m.lifespan,'spec']]){const el=document.createElement(tag);el.textContent=text;el.className=cls;content.append(el);}const link=document.createElement('a');link.href='#estimate';link.textContent='Plan with '+m.name+' ↗';link.onclick=()=>{$('#material').value=m.id;updateQuote();};content.append(link);card.append(content);$('#material-cards').append(card);}
for(const photo of c.photos){const figure=document.createElement('figure');const img=document.createElement('img');img.src=photo.src;img.alt=photo.alt;img.loading='lazy';img.width=600;img.height=450;const cap=document.createElement('figcaption');cap.textContent=photo.caption;figure.append(img,cap);$('#gallery').append(figure);}
for(const service of c.services){const el=document.createElement('p');el.textContent='↗ '+service;$('#services').append(el);}
function options(id,items){const sel=$('#'+id);items.forEach(x=>{const o=document.createElement('option');o.value=x.value;o.textContent=x.label;sel.append(o);});}
options('material',c.materials.map(m=>({value:m.id,label:m.name})));options('height',c.quote.heights);options('gates',c.quote.gates);$('#material').value=c.quote.defaultMaterial;$('#height').value=c.quote.defaultHeight;$('#footage').value=c.quote.defaultFootage;
function quote(){const material=c.materials.find(m=>m.id===$('#material').value),height=c.quote.heights.find(h=>h.value===$('#height').value),gate=c.quote.gates.find(g=>g.value===$('#gates').value),feet=Number($('#footage').value);return{material,height,gate,feet,low:Math.round(feet*material.low*height.factor+gate.low),high:Math.round(feet*material.high*height.factor+gate.high)};}
function updateQuote(){const q=quote();$('#range').textContent=$('#footage').checkValidity()?`${money(q.low)} – ${money(q.high)}`:'Enter 10–10,000 feet';}
['material','height','gates','footage'].forEach(id=>$('#'+id).addEventListener('input',updateQuote));updateQuote();
$('#lead-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.currentTarget),q=quote();const message=[`Free estimate request for ${c.name}`,`Name: ${f.get('name')}`,`Phone: ${f.get('phone')}`,`Email: ${f.get('email')||'Not provided'}`,`Location: ${f.get('city')}`,`Material: ${q.material.name}`,`Height: ${q.height.label}`,`Rough footage: ${q.feet} ft`,`Gates: ${q.gate.label}`,`Provisional planning range: ${money(q.low)}–${money(q.high)}`,c.copy.priceNote,`Details: ${f.get('details')||'None added'}`].join('\n');const channel=e.submitter?.value||'whatsapp';const url=channel==='email'?`mailto:${c.email}?subject=${encodeURIComponent('Free fence estimate request')}&body=${encodeURIComponent(message)}`:`https://wa.me/${c.whatsapp}?text=${encodeURIComponent(message)}`;if(channel==='email')location.href=url;else window.open(url,'_blank','noopener');put('send-status',channel==='email'?'Email draft prepared. Review and send in your email app.':'WhatsApp draft prepared. If the number is unavailable on WhatsApp, use email or the official contact form.');});
